import { useState } from 'react'
import { describeError } from '../api/client'
import { useSession } from '../session/session-context'

// Downloads a file generated by the API (a PDF, an Excel export…). The server
// applies the same access rules as viewing the data.
export function DownloadButton({
  path,
  fallbackName,
  label,
  busyLabel,
}: {
  path: string
  // Used when the server sends no file name (include the extension).
  fallbackName: string
  label: string
  busyLabel: string
}) {
  const { download } = useSession()
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const run = async () => {
    setBusy(true)
    setError(null)
    try {
      const { blob, filename } = await download(path)
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = filename ?? fallbackName
      document.body.append(link)
      link.click()
      link.remove()
      setTimeout(() => URL.revokeObjectURL(url), 10_000)
    } catch (err) {
      setError(describeError(err))
    } finally {
      setBusy(false)
    }
  }

  return (
    <>
      <button type="button" className="button button-secondary" disabled={busy} onClick={() => void run()}>
        {busy ? busyLabel : label}
      </button>
      {error ? <span className="field-error" role="alert">{error}</span> : null}
    </>
  )
}

// PDF of a quote or a sales order.
export function DownloadPdfButton({ path, fallbackName }: { path: string; fallbackName: string }) {
  return <DownloadButton path={path} fallbackName={`${fallbackName}.pdf`} label="Descargar PDF" busyLabel="Generando PDF…" />
}
